python - <<'PY'
from toggle import parse_toggle

cases = {
    "on": True,
    " ON ": True,
    "On": True,
    "off": False,
    " OFF ": False,
    "oFf": False,
    "unset": None,
    " UNSET ": None,
    "": ValueError,
    "   ": ValueError,
    "maybe": ValueError,
    "on now": ValueError,
}

for raw, expected in cases.items():
    try:
        actual = parse_toggle(raw)
    except Exception as exc:
        if not (isinstance(expected, type) and isinstance(exc, expected)):
            raise AssertionError(f"{raw!r}: unexpected exception {exc!r}") from exc
    else:
        if isinstance(expected, type) or actual is not expected:
            raise AssertionError(f"{raw!r}: expected {expected!r}, got {actual!r}")

for raw in (None, 1, b"on"):
    try:
        parse_toggle(raw)
    except ValueError:
        pass
    else:
        raise AssertionError(f"non-string input {raw!r} did not raise ValueError")

print(f"passed {len(cases) + 3} parse_toggle tests")
PY
